{
  "name": "串口实验仪器",
  "name_en": "Serial Laboratory Instrument",
  "manufacturer": "",
  "description": "一种通过串行端口与计算机交换文本命令和响应的通用实验室仪器或控制器。它通常用于接收控制指令、返回测量值或状态信息，并可进行端口发现、通信测试和设备识别。该类设备常见于各类实验室控制器、位移台控制器及其他基于串口通信的仪器。",
  "description_en": "A general laboratory instrument or controller that exchanges text commands and responses with a computer over a serial port. It is typically used to accept control commands, return measurements or status information, and support port discovery, communication testing, and device identification. Devices of this kind are common among lab controllers, stage controllers, and other serially connected instruments.",
  "tag_hints": [
    "serial communication",
    "text command interface",
    "lab instrument control",
    "device status query",
    "serial port autodetection",
    "stage controller"
  ],
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开与仪器的串口通信连接。",
      "description_en": "Open the serial communication connection to the instrument."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与仪器的串口通信连接。",
      "description_en": "Close the serial communication connection to the instrument."
    },
    {
      "action_name": "auto-write",
      "description": "向仪器发送一条串口文本命令。",
      "description_en": "Send a text command to the instrument over the serial port."
    },
    {
      "action_name": "auto-flush_input_buffer",
      "description": "清空仪器串口输入缓冲区中的待读数据。",
      "description_en": "Clear any pending data from the instrument's serial input buffer."
    },
    {
      "action_name": "auto-readline",
      "description": "从仪器读取一行串口返回信息。",
      "description_en": "Read a single line of serial response from the instrument."
    },
    {
      "action_name": "auto-read_multiline",
      "description": "从仪器连续读取多行串口返回信息。",
      "description_en": "Read multiple lines of serial response from the instrument."
    },
    {
      "action_name": "auto-query",
      "description": "向仪器发送查询命令并读取其响应。",
      "description_en": "Send a query command to the instrument and read its response."
    },
    {
      "action_name": "auto-parsed_query",
      "description": "向仪器发送查询命令，并按指定格式解析返回结果。",
      "description_en": "Send a query command to the instrument and parse the returned result in a specified format."
    },
    {
      "action_name": "auto-int_query",
      "description": "查询仪器并将返回值解析为整数。",
      "description_en": "Query the instrument and parse the returned value as an integer."
    },
    {
      "action_name": "auto-float_query",
      "description": "查询仪器并将返回值解析为浮点数。",
      "description_en": "Query the instrument and parse the returned value as a floating-point number."
    },
    {
      "action_name": "auto-test_communications",
      "description": "测试仪器当前串口通信是否正常。",
      "description_en": "Test whether serial communication with the instrument is working correctly."
    },
    {
      "action_name": "auto-find_port",
      "description": "搜索并识别仪器所连接的串口端口。",
      "description_en": "Search for and identify the serial port to which the instrument is connected."
    },
    {
      "action_name": "auto-communications_lock",
      "description": "获取通信总线访问锁状态。",
      "description_en": "get the communication bus access lock state"
    },
    {
      "action_name": "auto-available",
      "description": "检查设备是否可用。",
      "description_en": "Check whether the device is available."
    },
    {
      "action_name": "auto-confirm_available",
      "description": "确认设备当前可用并可响应通信。",
      "description_en": "Confirm that the device is currently available and responsive."
    },
    {
      "action_name": "auto-describe",
      "description": "获取设备的文字描述或识别信息。",
      "description_en": "Get a textual description or identification information for the device."
    }
  ]
}

